
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_pi_m06_2x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_pi_m06_2x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.968519752562645e+00, -1.934823265294190e+00, -1.887953738370666e+00, -1.822870133115065e+00, -1.731359936772647e+00, -1.598467317217580e+00, -1.405353133827557e+00, -1.182130614148661e+00, -1.006264475061343e+00, -7.262689934157456e-01, -5.130217241774708e-01, -3.225687476077659e-01, -2.707215047792796e-01, -2.267065405440802e-01, -1.736847404855517e-01, -1.140011391751240e-01, -5.469052744630259e-02, -2.484380466317109e-02, -5.829818768488720e-03, -6.583707771783102e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


